fn element_wise_divide(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // The two input arrays must have the same length.
    assert_eq!(arr1.len(), arr2.len(), "Input arrays must have the same length");

    // We'll build the result by zipping the two arrays together.
    let mut result = Vec::with_capacity(arr1.len());
    for (a, b) in arr1.iter().zip(arr2.iter()) {
        // We assume b != 0 and that (a / b) fits in a 32-bit signed integer.
        result.push(a / b);
    }
    result
}

